    private static async Task PreviewRadial()
    {Click(Named<Button>("PreviewArrangementButton"));await Idle();Assert(editor.Snapshot.Preview?.Request is RadialArrayRequest,"Radial preview failed: "+Named<TextBlock>("Status").Text);}
    private static double RadialNumber(string name)=>double.Parse(Named<TextBox>(name).Text,CultureInfo.CurrentCulture);
    private static void CheckRadialCopies(EditorSnapshot accepted,GeometryPreview preview)
    {
        var request=(RadialArrayRequest)preview.Request;var sources=accepted.Scene.Objects.Where(o=>accepted.SelectedObjectIds.Contains(o.Id)).ToArray();var copies=ArrayCopies(accepted,preview);
        Assert(copies.Length==sources.Length*(request.Count-1),"Radial copy count differs from Count including original.");
        foreach(var original in accepted.Scene.Objects)Assert(preview.Scene.Objects.Single(o=>o.Id==original.Id)==original,"Radial changed an original or unrelated leaf.");
        var center=Bounds3.From(sources.SelectMany(o=>new[]{o.Bounds.Min,o.Bounds.Max})).Center;
        for(var cell=1;cell<request.Count;cell++)
        {
            var a=request.AngleStepDegrees*cell;var rotation=Affine.RotateAbout(request.Axis switch{RadialArrayAxis.X=>new(a,0,0),RadialArrayAxis.Y=>new(0,a,0),_=>new Vec3(0,0,a)},request.PivotMillimeters);
            var step=request.RotateCopies?rotation:Affine.Translation(rotation.Apply(center)-center);
            for(var i=0;i<sources.Length;i++)
            {var source=sources[i];var copy=copies[(cell-1)*sources.Length+i];var expected=source.Transform.Then(step);Assert(ReferenceEquals(copy.Mesh,source.Mesh)&&copy.Material==source.Material&&ReferenceEquals(copy.TriangleMaterials,source.TriangleMaterials),"Radial lost source geometry/material.");foreach(var v in source.Mesh.Vertices) {var d=copy.Transform.Apply(v)-expected.Apply(v);Assert(Math.Abs(d.X)<.001&&Math.Abs(d.Y)<.001&&Math.Abs(d.Z)<.001,"Radial placement/orientation differs from request.");}}
        }
        Assert(request.ObjectIds.SequenceEqual(accepted.SelectedObjectIds)&&preview.SelectedObjectIds.SequenceEqual(copies.Select(o=>o.Id)),"Radial source authority or new-copy selection was lost.");
    }
